import{_ as d,o as e,c as o,a3 as r}from"./chunks/framework.B5WAEDB7.js";const S=JSON.parse('{"title":"数据模型","description":"","frontmatter":{},"headers":[],"relativePath":"backend/data-model.md","filePath":"backend/data-model.md","lastUpdated":1786258579000}'),a={name:"backend/data-model.md"};function c(s,t,i,n,_,h){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="数据模型" tabindex="-1">数据模型 <a class="header-anchor" href="#数据模型" aria-label="Permalink to &quot;数据模型&quot;">​</a></h1><p>数据表清单，按业务域分组（<code>XiHan.BasicApp.Saas</code> 与 <code>XiHan.BasicApp.Workflow</code> 两个模块；代码生成、AI 模块的表不在此列）。想知道某张表归谁管、某个功能落在哪张表，看这页。</p><p>实体基类、列约定、软删与索引规范见 <a href="./entity">实体基类</a>；连接与初始化见 <a href="./database">数据库配置</a>。</p><h2 id="命名速查" tabindex="-1">命名速查 <a class="header-anchor" href="#命名速查" aria-label="Permalink to &quot;命名速查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>约定</th><th>值</th></tr></thead><tbody><tr><td>表名前缀</td><td><code>Sys_</code></td></tr><tr><td>命名风格</td><td><code>snake_case</code></td></tr><tr><td>主键列</td><td><strong><code>Basic_Id</code></strong>（不是 <code>Id</code>）</td></tr><tr><td>多租户列</td><td><code>Tenant_Id</code>，<strong>全局记录 = 0</strong></td></tr><tr><td>软删列</td><td><code>Is_Deleted</code></td></tr><tr><td>分表后缀</td><td><code>_{year}{month}{day}</code> + <code>SplitType.Month</code>（按月，形如 <code>_20260801</code>）</td></tr></tbody></table><h2 id="身份与安全" tabindex="-1">身份与安全 <a class="header-anchor" href="#身份与安全" aria-label="Permalink to &quot;身份与安全&quot;">​</a></h2><table tabindex="0"><thead><tr><th>表</th><th>实体</th><th>说明</th></tr></thead><tbody><tr><td><code>Sys_User</code></td><td><code>SysUser</code></td><td>用户主体，<code>Email</code> 全平台唯一</td></tr><tr><td><code>Sys_User_Security</code></td><td><code>SysUserSecurity</code></td><td>一对一安全扩展：密码哈希、锁定、MFA、多端策略</td></tr><tr><td><code>Sys_User_Session</code></td><td><code>SysUserSession</code></td><td>会话中心（多端控制、撤销）</td></tr><tr><td><code>Sys_User_Setting</code></td><td><code>SysUserSetting</code></td><td>用户 UI 偏好（按场景 + key 存 JSON）</td></tr><tr><td><code>Sys_User_Statistics</code></td><td><code>SysUserStatistics</code></td><td>用户统计</td></tr><tr><td><code>Sys_User_Api_Credential</code></td><td><code>SysUserApiCredential</code></td><td>开放接口个人凭证（AppKey + AppSecret 密文，Data Protection 可逆加密）</td></tr><tr><td><code>Sys_External_Login</code></td><td><code>SysExternalLogin</code></td><td>第三方身份绑定</td></tr><tr><td><code>Sys_Password_History</code></td><td><code>SysPasswordHistory</code></td><td>历史密码（防重用）</td></tr></tbody></table><p>→ <a href="./authentication">统一认证</a></p><h2 id="权限与授权" tabindex="-1">权限与授权 <a class="header-anchor" href="#权限与授权" aria-label="Permalink to &quot;权限与授权&quot;">​</a></h2><table tabindex="0"><thead><tr><th>表</th><th>实体</th><th>说明</th></tr></thead><tbody><tr><td><code>Sys_Role</code> / <code>Sys_Role_Hierarchy</code></td><td><code>SysRole</code> / <code>SysRoleHierarchy</code></td><td>角色与层级继承（闭包）</td></tr><tr><td><code>Sys_Permission</code></td><td><code>SysPermission</code></td><td>权限点</td></tr><tr><td><code>Sys_Operation</code> / <code>Sys_Resource</code></td><td><code>SysOperation</code> / <code>SysResource</code></td><td>操作字典与资源，<strong>权限由「资源 × 操作」派生</strong></td></tr><tr><td><code>Sys_Role_Permission</code> / <code>Sys_User_Permission</code></td><td>—</td><td>角色授权 / 用户直授</td></tr><tr><td><code>Sys_Role_Data_Scope</code> / <code>Sys_User_Data_Scope</code></td><td>—</td><td>自定义数据范围</td></tr><tr><td><code>Sys_Permission_Condition</code></td><td><code>SysPermissionCondition</code></td><td>ABAC 属性条件</td></tr><tr><td><code>Sys_Permission_Delegation</code></td><td><code>SysPermissionDelegation</code></td><td>权限委托</td></tr><tr><td><code>Sys_Permission_Request</code></td><td><code>SysPermissionRequest</code></td><td>权限申请</td></tr><tr><td><code>Sys_Field_Level_Security</code></td><td><code>SysFieldLevelSecurity</code></td><td>字段级安全（可读 / 可编辑 / 脱敏策略）</td></tr><tr><td><code>Sys_Constraint_Rule</code> / <code>Sys_Constraint_Rule_Item</code></td><td>—</td><td>约束规则引擎（SSD / DSD / 互斥 / 基数…）</td></tr><tr><td><code>Sys_Session_Role</code></td><td><code>SysSessionRole</code></td><td>会话角色映射</td></tr></tbody></table><p>→ <a href="./permission">权限管理</a> · <a href="./data-permission">数据权限</a> · <a href="./approval">审批与约束</a></p><h2 id="组织与租户" tabindex="-1">组织与租户 <a class="header-anchor" href="#组织与租户" aria-label="Permalink to &quot;组织与租户&quot;">​</a></h2><table tabindex="0"><thead><tr><th>表</th><th>实体</th><th>说明</th></tr></thead><tbody><tr><td><code>Sys_Department</code> / <code>Sys_Department_Hierarchy</code></td><td>—</td><td>部门树与<strong>闭包表</strong></td></tr><tr><td><code>Sys_Position</code></td><td><code>SysPosition</code></td><td>岗位字典</td></tr><tr><td><code>Sys_User_Department</code></td><td><code>SysUserDepartment</code></td><td>用户多部门归属（主部门、岗位、工号）</td></tr><tr><td><code>Sys_User_Role</code></td><td><code>SysUserRole</code></td><td>用户角色（支持生效期）</td></tr><tr><td><code>Sys_Tenant</code></td><td><code>SysTenant</code></td><td>租户</td></tr><tr><td><code>Sys_Tenant_User</code></td><td><code>SysTenantUser</code></td><td>租户成员关系</td></tr><tr><td><code>Sys_Tenant_Edition</code> / <code>Sys_Tenant_Edition_Permission</code></td><td>—</td><td>版本套餐与可用权限白名单</td></tr></tbody></table><p>→ <a href="./organization">组织架构</a> · <a href="./multi-tenancy">多租户 SaaS</a></p><h2 id="系统设置" tabindex="-1">系统设置 <a class="header-anchor" href="#系统设置" aria-label="Permalink to &quot;系统设置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>表</th><th>实体</th><th>说明</th></tr></thead><tbody><tr><td><code>Sys_Menu</code></td><td><code>SysMenu</code></td><td>菜单（<code>PageRegistry</code> 的落库形态）</td></tr><tr><td><code>Sys_Dict</code> / <code>Sys_Dict_Item</code></td><td>—</td><td>数据字典</td></tr><tr><td><code>Sys_Config</code></td><td><code>SysConfig</code></td><td>参数配置</td></tr><tr><td><code>Sys_Numbering_Rule</code> / <code>Sys_Numbering_Allocation</code></td><td>—</td><td>业务编号规则与分配记录</td></tr><tr><td><code>Sys_Version</code></td><td><code>SysVersion</code></td><td>版本管理</td></tr><tr><td><code>Sys_Migration_History</code></td><td><code>SysMigrationHistory</code></td><td>升级迁移历史</td></tr></tbody></table><p>→ <a href="./settings">系统设置</a></p><h2 id="消息与通知" tabindex="-1">消息与通知 <a class="header-anchor" href="#消息与通知" aria-label="Permalink to &quot;消息与通知&quot;">​</a></h2><table tabindex="0"><thead><tr><th>表</th><th>实体</th><th>说明</th></tr></thead><tbody><tr><td><code>Sys_Notification</code> / <code>Sys_User_Notification</code></td><td>—</td><td>通知公告与逐用户接收状态</td></tr><tr><td><code>Sys_User_Notification_Preference</code></td><td>—</td><td>通知偏好（渠道 × 类型）</td></tr><tr><td><code>Sys_Message_Template</code></td><td><code>SysMessageTemplate</code></td><td>消息模板（Scriban）</td></tr><tr><td><code>Sys_Email</code> / <code>Sys_Email_Config</code></td><td>—</td><td>邮件记录与网关配置</td></tr><tr><td><code>Sys_Sms</code> / <code>Sys_Sms_Config</code></td><td>—</td><td>短信记录与网关配置</td></tr><tr><td><code>Sys_Bot_Config</code></td><td><code>SysBotConfig</code></td><td>钉钉 / 飞书 / 企业微信 Webhook 机器人</td></tr><tr><td><code>Sys_Telegram_Bot</code></td><td><code>SysTelegramBot</code></td><td>多实例 Telegram Bot</td></tr><tr><td><code>Sys_Chat_Conversation</code> / <code>_Member</code> / <code>Sys_Chat_Message</code> / <code>_Reaction</code></td><td>—</td><td>在线聊天</td></tr></tbody></table><p>→ <a href="./messaging">消息通知</a> · <a href="./realtime">即时通讯</a></p><h2 id="文件与任务" tabindex="-1">文件与任务 <a class="header-anchor" href="#文件与任务" aria-label="Permalink to &quot;文件与任务&quot;">​</a></h2><table tabindex="0"><thead><tr><th>表</th><th>实体</th><th>说明</th></tr></thead><tbody><tr><td><code>Sys_File</code> / <code>Sys_File_Storage</code></td><td>—</td><td>文件元数据与存储位置（一对多）</td></tr><tr><td><code>Sys_Storage_Config</code></td><td><code>SysStorageConfig</code></td><td>存储后端配置（本地 / S3 / OSS / COS / MinIO）</td></tr><tr><td><code>Sys_Export_Task</code></td><td><code>SysExportTask</code></td><td>异步导出任务</td></tr><tr><td><code>Sys_Import_History</code></td><td><code>SysImportHistory</code></td><td>导入历史</td></tr><tr><td><code>Sys_Task</code></td><td><code>SysTask</code></td><td>定时任务定义</td></tr></tbody></table><p>→ <a href="./file">文件与存储</a> · <a href="./scheduling">定时任务</a></p><h2 id="开放能力与审批" tabindex="-1">开放能力与审批 <a class="header-anchor" href="#开放能力与审批" aria-label="Permalink to &quot;开放能力与审批&quot;">​</a></h2><table tabindex="0"><thead><tr><th>表</th><th>实体</th><th>说明</th></tr></thead><tbody><tr><td><code>Sys_OAuth_App</code> / <code>Sys_OAuth_Code</code> / <code>Sys_OAuth_Token</code></td><td>—</td><td>作为 OAuth2 / OIDC <strong>服务端</strong>的应用、授权码与令牌</td></tr><tr><td><code>Sys_Review</code></td><td><code>SysReview</code></td><td>审批 / 审查单</td></tr></tbody></table><p>→ <a href="./open-api">开放接口</a> · <a href="./approval">审批与约束</a></p><h2 id="工作流" tabindex="-1">工作流 <a class="header-anchor" href="#工作流" aria-label="Permalink to &quot;工作流&quot;">​</a></h2><p><code>XiHan.BasicApp.Workflow</code> 模块的四张表：</p><table tabindex="0"><thead><tr><th>表</th><th>实体</th><th>说明</th></tr></thead><tbody><tr><td><code>Sys_Workflow_Definition</code></td><td><code>SysWorkflowDefinition</code></td><td>流程定义</td></tr><tr><td><code>Sys_Workflow_Instance</code></td><td><code>SysWorkflowInstance</code></td><td>流程实例</td></tr><tr><td><code>Sys_Workflow_Node_Instance</code></td><td><code>SysWorkflowNodeInstance</code></td><td>节点实例</td></tr><tr><td><code>Sys_Workflow_Bookmark</code></td><td><code>SysWorkflowBookmark</code></td><td>书签（挂起点）</td></tr></tbody></table><p>→ <a href="./workflow">工作流</a></p><h2 id="日志-均按月分表" tabindex="-1">日志（均按月分表） <a class="header-anchor" href="#日志-均按月分表" aria-label="Permalink to &quot;日志（均按月分表）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>表</th><th>说明</th></tr></thead><tbody><tr><td><code>Sys_Access_Log</code></td><td>访问日志</td></tr><tr><td><code>Sys_OpenApi_Log</code></td><td>开放接口日志</td></tr><tr><td><code>Sys_Operation_Log</code></td><td>操作日志</td></tr><tr><td><code>Sys_Login_Log</code></td><td>登录日志</td></tr><tr><td><code>Sys_Exception_Log</code></td><td>异常日志</td></tr><tr><td><code>Sys_Diff_Log</code></td><td>数据变更日志（需开 <code>EnableDiffLog</code>）</td></tr><tr><td><code>Sys_Permission_Change_Log</code></td><td>权限变更日志</td></tr><tr><td><code>Sys_Review_Log</code></td><td>审批日志</td></tr><tr><td><code>Sys_Task_Log</code></td><td>任务执行日志</td></tr><tr><td><code>Sys_Telegram_Message</code></td><td>Telegram 出站审计</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">分表查询要带时间范围</p><p>物理表名形如 <code>Sys_Access_Log_20260801</code>，要走 SqlSugar 的分表 API 按时间定位，不能当普通表直接查。</p></div><p>→ <a href="./logging">日志审计</a></p><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li><a href="./entity">实体基类</a>：基类选型与列约定</li><li><a href="./database">数据库配置</a>：连接、初始化、分表</li><li><a href="./introduction">框架简介</a>：模块与分层</li></ul>',36)])])}const l=d(a,[["render",c]]);export{S as __pageData,l as default};
